by('cgPrimary').onclick=async e=>{
 if(e.detail>1)return;
 if(busy){if(searching)stopSearch('cancelled');else by('cgStop').click();return;}
 if(previewState){if(workspaceView==='solutions'&&selectedChoice!==previewState.id)previewChoice(selectedChoice);else applyPreview();return;}
 if(dirty||workspaceView==='data'){await runFromData();return;}
 if(workspaceView==='results'&&appliedCurrent()){if(!formReady)drawForm(false);show('data');return;}
 if(workspaceView==='solutions'){
  if(['no_fault','conflict','insufficient_observation'].includes(searchRecord?.status)&&recordMatches()){
   if(searchRecord.status==='conflict'){openSetting('cg-hours');return;}
   if(!formReady)drawForm(false);show('data');
   if(searchRecord.status==='insufficient_observation'){
    const field=by('cg-budget');field.closest('details').open=true;field.focus();
   }else{
    by('cgGoals').open=true;
    if(searchRecord.status==='no_fault'){by('cgGoalMode').value='set';by('cgGoalFields').hidden=false;dirty=true;}
    by('cgGoalMin').focus();
   }
   updateChrome();return;
  }
  if(selectedChoice&&recordMatches()){previewChoice(selectedChoice);return;}
  if(!currentRuns().length){await simulate(false);return;}
  await startSearch();return;
 }
 if(workspaceView==='results'){if(searchRecord&&recordMatches()){renderSearch();show('solutions');}else await startSearch();return;}
 await simulate(false);
};
