function changeText(row){return row.path.map(p=>{const k=searchRecord.knobs.find(k=>k.id===p.id);if(k.template)return k.label+'：'+JSON.stringify(k.template);const ratio=k.current?p.value/k.current:null,amount=ratio!==null&&(ratio>=1.5||ratio<=2/3)?'（'+(ratio<.01?'降至原来的'+pretty(ratio*100)+'%':pretty(ratio)+'倍')+'）':'';if(k.id==='enemy_hp')return '敌人生命 '+pretty(searchRecord.game.world.enemy.hp)+' → '+pretty(row.game.world.enemy.hp)+amount+(searchRecord.game.world.steps.hp!==undefined?'；每关增加 '+pretty(searchRecord.game.world.steps.hp)+' → '+pretty(row.game.world.steps.hp):'');if(k.fields?.length===2)return '物理伤害 '+k.fields.map(f=>pretty(searchRecord.game.player[f])).join('–')+' → '+k.fields.map(f=>pretty(row.game.player[f])).join('–')+amount;return (k.id==='cost'?'原卡点同笔升级':k.label)+' '+pretty(k.current*((k.id.startsWith('resist_')||k.id==='armor'&&ConnectedCore.rules.defense(game)==='ratio')?100:1))+' → '+pretty(p.value*((k.id.startsWith('resist_')||k.id==='armor'&&ConnectedCore.rules.defense(game)==='ratio')?100:1))+((k.id.startsWith('resist_')||k.id==='armor'&&ConnectedCore.rules.defense(game)==='ratio')?'%':'')+amount;}).join('；');}
function tradeoffText(row){const out=[paceText(row.grade.before,row.grade.after)],rs=[...row.discovery,...row.validation],range=key=>{const a=rs.map(r=>num(r[key]));return pretty(Math.min(...a))+(Math.min(...a)!==Math.max(...a)?'–'+pretty(Math.max(...a)):'');};for(const p of row.path){const k=searchRecord.knobs.find(k=>k.id===p.id);if(k.template)out.push(k.label+'曲线替换；逐级收益或价格按新规则重算');else if(k.id==='cost')out.push('金币换等级的门槛降低');else if(k.id==='income')out.push('本轮固定发币 '+range('passiveEarned'));else if(k.id==='reward')out.push('本轮首通发币 '+range('rewardsEarned'));else if(k.id==='hp'||k.id==='armor')out.push('生存压力降低');else if(k.fields)out.push(p.value>k.current?'基础输出提高':'每击输出降低');else if(k.id==='enemy_hp')out.push(p.value>k.current?'每关血量要求提高':'每关血量要求降低');else if(k.id==='frequency')out.push('每次出手 '+time(1/k.current)+' → '+time(1/p.value));else if(k.id==='visits')out.push('每天多打开'+(p.value-k.current)+'次，总在线分钟不变');else if(k.upgrade)out.push('同一次升级获得更多属性');else if(k.field)out.push('敌人抗性降低');}return out.join('；');}
