 const ids=r.recommendations||[],stale=dirty||!recordMatches()&&!previewState,status={complete:'搜索完成',interrupted_import:'已恢复中断搜索，可继续',cancelled:'搜索已停止',time_budget:'达到运行时限',run_budget:'达到试算次数上限',event_budget:'达到累计事件上限',candidate_budget:'达到本记录候选上限',conflict:'目标冲突',insufficient_observation:'观察期不足',baseline_error:'基准计算中断',already_meets:'当前方案符合目标，建议保持',no_fault:'当前已全部通过',error:'搜索中断'}[r.status]||'搜索进行中';
 by('cgSearchState').textContent=stale?'配置或目标已改，旧推荐已失效；需重新检查和搜索。':r.status==='conflict'?'目标冲突：回访空档超过了等待目标。':status+(ids.length?' · 找到'+ids.length+'个已核对方案':r.reason&&r.status!=='already_meets'?' · '+r.reason:'');if(!stale&&r.status==='conflict')showConflict(r);if(!searchChoiceAllowed(r,selectedChoice))selectedChoice=ids[0]||null;
 by('cgSearchCards').innerHTML=ids.slice(0,searchVisible).map((id,index)=>{const row=r.rows.find(x=>x.id===id),verdict=stale?'旧配置结果，需重新核对':row.grade.hasGoals&&!row.grade.allMet?'部分改善，仍未达标：'+goalText(r.game,row.grade):goalText(r.game,row.grade);return '<article class="cg-choice'+(id===selectedChoice?' cg-choice-selected':'')+'"><input type="radio" name="cgChoice" value="'+id+'" aria-label="选择方案'+(index+1)+'"'+(id===selectedChoice?' checked':'')+(stale?' disabled':'')+'><div><h3>方案'+(index+1)+' · '+escape(r.knobs.find(k=>k.id===row.path[0].id).label)+'</h3><p class="cg-verdict">'+escape(verdict)+'</p><p>'+escape(changeText(row))+'</p><p>主要收益：'+escape(benefitText(row.grade))+'</p><p class="cg-pace-change">节奏与代价：'+escape(tradeoffText(row))+'</p></div><button type="button" data-search-preview="'+id+'"'+(stale?' disabled':'')+'>预览</button></article>';}).join('');
 const summary='<p>搜索编号：'+r.seeds.discovery.join('、')+'；独立核对：'+r.seeds.validation.join('、')+'。</p><p>'+r.runs+'次试算，'+r.rows.length+'组修改，'+r.events+'个事件；'+Math.round((r.elapsedMs||0)/1000)+'秒。</p><p>本次有界搜索只改允许的数值和明确勾选的规则模板，最多同时修改'+(r.options.maxJoint||2)+'项。状态、反应和受限公式可手工修改，重新核验后对照；本轮未穷举所有组合。</p><p>生成规则 '+escape(r.version)+'；评价规则 '+escape(r.evaluationVersion||r.version)+'。等待不足1秒或原等待1%的变化，不单独作为明显收益。</p>';by('cgSearchAudit').innerHTML=summary+r.rows.map(row=>'<p>'+escape(row.id+'：'+(row.path||[]).map(p=>(r.knobs.find(k=>k.id===p.id)?.label||p.id)+'='+pretty(p.value)).join('；'))+' · '+escape(row.verified?'已核对':row.state==='invalid'?'配置无效':'独立核对未完成')+(row.errors.length?' · '+escape(row.errors.map(e=>e.message).join('；')):'')+(row.grade?' · '+escape((row.decision||'搜索样本')+'；'+benefitText(row.grade)+'；'+(row.verified?goalText(r.game,row.grade):'搜索样本：'+goalText(r.game,row.grade)+'，待独立核对')):'')+'</p>').join('');for(const button of by('cgSearchCards').querySelectorAll('[data-search-preview]'))button.textContent=currentChoice(button.dataset.searchPreview)?'当前方案 · 查看结果':'预览';updateChrome();
