by('cgSearchCards').onchange=e=>{if(e.target.name==='cgChoice'){selectedChoice=e.target.value;renderSearch();by('cgSearchCards').querySelector('input[value="'+selectedChoice+'"]')?.focus({preventScroll:true});}};by('cgSearchCards').onclick=e=>{const b=e.target.closest('[data-search-preview]');if(b)previewChoice(b.dataset.searchPreview);};
function previewChoice(id){if(!searchRecord||dirty||!previewState&&!recordMatches()){notice('数据已变，按当前配置重新搜索。',true);return;}const row=searchRecord.rows.find(x=>x.id===id);if(!row?.verified||!searchChoiceAllowed(searchRecord,id))return;if(currentChoice(id)){if(previewState){const original=previewState.original;previewState=null;restoreSnapshot(original);}selectedChoice=id;renderResults();showAppliedResult();notice('这个方案已是当前方案，无需再次应用。');return;}const original=previewState?.original||capture(),number=searchChoiceNumber(searchRecord,id);previewState={id,number,original};selectedChoice=id;baseGame=copy(searchRecord.game);baseRuns=copy([...searchRecord.baseDiscovery,...searchRecord.baseValidation]);game=copy(row.game);candidateRuns=copy([...row.discovery,...row.validation]);failures=[];dirty=false;formReady=false;selectedRun=candidateRuns[0];scrollPlaces.results=0;renderResults();show('results');notice('已打开方案'+number+'预览，确认后再应用。');}
function cancelPreview(){if(!previewState)return;const original=previewState.original;previewState=null;restoreSnapshot(original);renderSearch();show('solutions',{remember:false});}
function applyPreview(){if(!previewState)return;if(fingerprint(game)===fingerprint(previewState.original.game)){const original=previewState.original;previewState=null;restoreSnapshot(original);renderResults();showAppliedResult();notice('当前已使用这些参数，无需重复应用。');return;}const selected=selection();appliedUndo=previewState.original;appliedName='方案'+previewState.number;const {history:oldHistory,...audit}=copy(appliedUndo);history.push({type:'before_search_application',...audit});previewState=null;savedWorkspace=false;renderResults();applySelection(selected);showAppliedResult();notice(appliedName+'已应用，当前参数已更新。');}
function undoApplication(){if(!appliedUndo)return;const old=appliedUndo,{history:oldHistory,...snapshot}=capture(),audit={type:'undone_search_application',...snapshot};appliedUndo=null;previewState=null;restoreSnapshot(old);history.push(audit);savedWorkspace=false;renderResults();renderSearch();showAppliedResult();notice('已撤销本次应用，恢复应用前的方案。');}
const exportCore=project;project=function(includeResults=false){return {...exportCore(includeResults),searchOptions:optionsFromFormSafe(),workspace:{appliedName,selectedChoice,view:workspaceView,scrollPlaces:{...copy(scrollPlaces),[workspaceView]:window.scrollY},selection:selection(),preview:includeResults?previewState:null},...(includeResults?{search:searchRecord,searchHistory,applicationUndo:appliedUndo,progressAttribution:{version:ConnectedCore.PROGRESS_GAP_VERSION,definition:'longestGap保留全部未推进时间，含离线；分项互不重复',base:baseRuns.map(r=>ConnectedCore.progressGap(r)),candidate:candidateRuns.map(r=>ConnectedCore.progressGap(r)),selected:selectedRun?ConnectedCore.progressGap(selectedRun,selectedStage):null}}:{} )};};
function optionsFromFormSafe(){try{return optionsFromForm();}catch{return null;}}
function validateSearch(r){ConnectedSearch.validateRecord(r);if(r?.status==='running')ConnectedSearch.finish(r,'interrupted_import');return r;}
function validateSnapshot(s){if(!s)return;ConnectedCore.compile(s.game);if(s.baseGame)ConnectedCore.compile(s.baseGame);validateStoredRuns(s.baseRuns);validateStoredRuns(s.candidateRuns);if(!Array.isArray(s.history)||!Array.isArray(s.failures))throw Error('工作区回退记录不完整');}
const loadCore=loadProject;loadProject=function(data){validateSearch(data.search);if(data.searchHistory&&!Array.isArray(data.searchHistory))throw Error('搜索历史格式不匹配');for(const r of data.searchHistory||[])validateSearch(r);validateSnapshot(data.applicationUndo);validateSnapshot(data.workspace?.preview?.original);loadCore(data);searchRecord=copy(data.search||null);searchHistory=copy(data.searchHistory||[]);selectedChoice=data.workspace?.selectedChoice||null;appliedName=typeof data.workspace?.appliedName==='string'?data.workspace.appliedName:'';appliedUndo=data.applicationUndo||null;previewState=data.workspace?.preview||null;pendingSearchOptions=data.searchOptions?copy(data.searchOptions):null;if(data.searchOptions){for(const[id,key]of [['cgSearchSeconds','seconds'],['cgSearchRuns','maxRuns'],['cgSearchEvents','maxEvents']])by(id).value=data.searchOptions[key];}if(data.workspace?.scrollPlaces)for(const[k,v]of Object.entries(data.workspace.scrollPlaces))if(['data','results','solutions','simulation','empty'].includes(k)&&Number.isFinite(v)&&v>=0)scrollPlaces[k]=v;by('cgSearchBounds').dataset.game='';by('cgSearchBounds').innerHTML='';prepareBounds();renderSearch();if(baseRuns.length||candidateRuns.length)renderResults();applySelection(data.workspace?.selection);if(data.workspace?.view==='solutions'&&searchRecord)show('solutions',{remember:false});else if(data.workspace?.view==='data'&&game){if(!formReady)drawForm(false);show('data',{remember:false});}updateChrome();};
const loadEvaluated=loadProject;loadProject=function(data){loadEvaluated(data);clearTransient({feedback:false});if(previewState){if(!searchChoiceAllowed(searchRecord,previewState.id)){const original=previewState.original;previewState=null;restoreSnapshot(original);renderSearch();show('solutions',{remember:false});notice('旧预览未通过本轮筛选，已恢复修改前配置。');}else{previewState.number=searchChoiceNumber(searchRecord,previewState.id);updateChrome();}}};
