function database(){return new Promise((resolve,reject)=>{const req=indexedDB.open('idle-connected-workspace',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result);});}
by('cgSave').onclick=async()=>{if(dirty)return;try{const db=await database(),tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(copy(project(true)),'current');await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();savedWorkspace=true;notice('工作区已保存到本机。');updateChrome();}catch(e){notice('本机保存失败，请导出完整结果：'+e.message,true);}};
by('cgRestore').onclick=async()=>{try{const db=await database(),tx=db.transaction('workspace','readonly'),req=tx.objectStore('workspace').get('current'),data=await new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});db.close();if(data)loadProject(data);else{const raw=localStorage.getItem(stateKey);if(!raw)throw Error('没有本机存档');loadProject(JSON.parse(raw));}savedWorkspace=true;filesDialog.close();updateChrome();notice('工作区已恢复。');}catch(e){notice(e.message,true);}};
